return $input.all().map(({ json: c }) => {
  let score = 0;
  const signals = [];

  const base = Number(c.base_actions), recent = Number(c.recent_actions);
  const drop = base > 0 ? 1 - recent / base : 0;
  if (drop >= 0.5) {
    score += 35;
    signals.push({ code: "USAGE_DROP_SEVERE", fact: `Key actions down ${Math.round(drop * 100)}% vs prior 8 weeks` });
  } else if (drop >= 0.25) {
    score += 20;
    signals.push({ code: "USAGE_DROP", fact: `Key actions down ${Math.round(drop * 100)}% vs prior 8 weeks` });
  }

  const idle = Math.floor((Date.now() - new Date(c.last_login_at)) / 86400000);
  if (idle > 21) {
    score += 25;
    signals.push({ code: "INACTIVE", fact: `No login for ${idle} days` });
  } else if (idle > 10) {
    score += 10;
    signals.push({ code: "LOW_LOGINS", fact: `Last login ${idle} days ago` });
  }

  const neg = Number(c.neg_tickets);
  if (neg >= 2) {
    score += 20;
    signals.push({ code: "NEG_TICKETS", fact: `${neg} negative support tickets in 30 days` });
  } else if (neg === 1) {
    score += 10;
    signals.push({ code: "NEG_TICKET", fact: "1 negative support ticket in 30 days" });
  }

  const failed = Number(c.failed_payments);
  if (failed >= 1) {
    score += 20;
    signals.push({ code: "PAYMENT_FAILED", fact: `${failed} failed payment(s) in 60 days` });
  }

  const daysToRenewal = Math.ceil((new Date(c.renewal_date) - Date.now()) / 86400000);
  if (daysToRenewal >= 0 && daysToRenewal <= 30) {
    score += 10;
    signals.push({ code: "RENEWAL_SOON", fact: `Renews in ${daysToRenewal} days` });
  }

  const tenure = Math.floor((Date.now() - new Date(c.signup_date)) / 86400000);
  if (tenure < 90) {
    score += 5;
    signals.push({ code: "NEW_CUSTOMER", fact: `Customer for only ${tenure} days` });
  }

  score = Math.min(score, 100);
  const tier = score >= 60 ? "high" : score >= 35 ? "medium" : "low";
  const path = tier === "high" && Number(c.mrr) >= 500 ? "human" : "auto";

  return { json: { ...c, risk_score: score, risk_tier: tier, signals, path } };
});

