const src = $('Loop Over Items').item.json;
const raw = $json.output?.[0]?.content?.[0]?.text ?? "";

const tone = src.signals.some(s => s.code === 'PAYMENT_FAILED')
  ? 'billing'
  : (src.signals.some(s => s.code.startsWith('NEG_TICKET')) ? 'support' : 'general');

const subjects = {
  general: "Checking in",
  billing: "Quick billing check",
  support: "Following up on your support experience"
};
const fallbackQuestion = {
  general: "Is there anything I can do to make things easier for you?",
  billing: "Is there anything I can help with on that front?",
  support: "Did everything get resolved to your satisfaction?"
};

// whole-word matches only, so "proactive" or "actively" do not trigger it
const survRe = /\b(notice[ds]?|noticing|noticeable|saw|seems?|appears?|looks like|logged|logging in|log in|logins?|usage|activity|inactive|inactivity|analytics|tracking|our data|dropped|declin\w+|decreas\w+|dormant|monitor\w*|haven'?t (?:been|used|seen))\b/i;

// the model should return plain text; if it returns JSON anyway, pull the body out
let core = raw.replace(/`/g, "").trim();
if (core.startsWith("{")) {
  try {
    core = String(JSON.parse(core).body || "").trim();
  } catch (e) {
    const m = core.match(/"body"\s*:\s*"([\s\S]*?)"\s*[,}]/);
    core = m ? m[1].replace(/\\n/g, " ").trim() : "";
  }
}
core = core.replace(/^["']+|["']+$/g, "").trim();

// strip any greeting or sign-off the model added anyway
core = core.replace(/^(hi|hello|hey|dear)\b[^\n]*?,\s*/i, "");
core = core.replace(/[\s,]*(best regards|kind regards|warm regards|regards|best|thanks|cheers|sincerely)?[,\s]*CJ\s*$/i, "").trim();
core = core.replace(/\s*\n+\s*/g, " ");

// REPAIR: drop risky sentences, keep only the last question, then make sure it ends with one question
const sentences = (core.match(/[^.?!]+[.?!]+(?:\s|$)|[^.?!]+$/g) || [core]).map(s => s.trim()).filter(Boolean);
const dropped = [];
const kept = sentences.filter(s => {
  if (survRe.test(s)) { dropped.push(s); return false; }
  return true;
});
const questions = kept.filter(s => s.endsWith("?"));
const statements = kept.filter(s => !s.endsWith("?"));
questions.slice(0, -1).forEach(q => dropped.push(q));
const finalQuestion = questions.length ? questions[questions.length - 1] : fallbackQuestion[tone];
core = [...statements, finalQuestion].join(" ");

const subject = subjects[tone];
const words = core.split(/\s+/).filter(Boolean).length;
const qCount = (core.match(/\?/g) || []).length;
const body = `Hi ${src.first_name},\n\n${core}\n\nCJ`;
const surv = core.match(survRe);

const checks = {
  hasBody:        core.length > 40,
  lengthOk:       words >= 20 && words <= 100,
  noPlaceholders: !/\[.*?\]|\{\{.*?\}\}|XYZ|Lorem/i.test(core),
  noOffers:       !/discount|\d+\s?%|free (month|trial)|coupon|refund|promo/i.test(core),
  noSurveillance: !surv,
  noEmDash:       !/[—–]/.test(core),
  noExclaim:      !/!/.test(core),
  noStrayNames:   !/\bCJ\b/.test(core) && !core.includes(src.first_name) && !core.includes(src.company),
  noPlanMention:  !new RegExp("\\b" + src.plan + "\\s+(plan|tier|subscription)\\b", "i").test(core),
  oneQuestion:    qCount === 1
};

const detail = {
  noSurveillance: surv ? `"${surv[0]}"` : "",
  oneQuestion:    `${qCount} question marks`,
  lengthOk:       `${words} words`
};

const failed = Object.entries(checks)
  .filter(([, v]) => !v)
  .map(([k]) => detail[k] ? `${k} (${detail[k]})` : k);

return { json: {
  ...src,
  tone,
  subject,
  body,
  word_count: words,
  repaired: dropped,
  valid: failed.length === 0,
  fail: failed.join(", "),
  raw_output: raw.slice(0, 500)
}};

