let p;
try {
  p = JSON.parse(raw.replace(/`/g, "").replace(/^json/i, "").trim());
} catch (e) {
  return { json: { ...src, valid: false, fail: "unparseable" } };
}

const summary = (p.summary || "").trim();
const reason = (p.likely_reason || "").trim();
const points = Array.isArray(p.talking_points) ? p.talking_points.map(t => String(t).trim()) : [];
const allText = [summary, reason, ...points].join(" ");

// every number the model mentions must come from the facts we gave it
const allowed = new Set(
  src.signals.flatMap(s => s.fact.match(/\d+/g) || [])
    .concat([String(src.risk_score), String(Math.round(Number(src.mrr)))])
);
const mentioned = allText.match(/\d+/g) || [];

const checks = {
  hasSummary:      summary.length > 20,
  summaryShort:    summary.split(/\s+/).filter(Boolean).length <= 45,
  reasonOk:        /^Possibly/.test(reason),
  pointsOk:        points.length >= 2 && points.length <= 4 && points.every(t => t.length > 10),
  noInventedNums:  mentioned.every(n => allowed.has(n)),
  noEmDash:        !/[—–]/.test(allText),
  noPlaceholders:  !/\[.*?\]|\{\{.*?\}\}|XYZ|Lorem/i.test(allText)
};

const failed = Object.entries(checks).filter(([, v]) => !v).map(([k]) => k);

return { json: {
  ...src,
  briefing: { summary, likely_reason: reason, talking_points: points },
  valid: failed.length === 0,
  fail: failed.join(",")
}};

