const reasonPhrase = {
  PRICE: "the cost was a concern",
  MISSING_FEATURE: "the product was missing something they needed",
  NOT_USING: "it was not the right fit at the time",
  SUPPORT_BAD: "their support experience fell short of what it should be",
  COMPETITOR: "",
  UNKNOWN: ""
};

return $input.all().map(({ json: l }) => {
  const t = Number(l.winback_touch);
  const updates = Array.isArray(l.updates) ? l.updates : [];
  let angle, subject, goal, fixed_line = "";

  if (t === 0) {
    angle = "thanks";
    subject = "Thank you, and one quick question";
    goal = "Thank them for having been a customer. Say you would value their honest feedback. Ask what one thing would have made them stay. No pitch and no offer.";
  } else if (t === 1) {
    if (l.cancel_reason === "MISSING_FEATURE" && updates.length) {
      angle = "updates";
      subject = "What is new since you left";
      goal = "Say you wanted to reach out with a quick note now that some time has passed. Do not mention the product, features, cost, or any changes, because a sentence with the details is added automatically. Ask whether they would like to take a look.";
      fixed_line = "Here is what we have shipped since you left: " + updates.map(u => u.title).join(", ") + ".";
    } else if (l.cancel_reason === "PRICE" && l.discount_pct > 0) {
      angle = "offer";
      subject = "A thought on pricing";
      goal = "Acknowledge that cost was a concern, kindly. Say you would like to make it easier for them to come back. Ask whether they would like to take a second look.";
      fixed_line = "We can offer " + l.offer_desc + " if you decide to come back.";
    } else if (["NOT_USING", "SUPPORT_BAD"].includes(l.cancel_reason) && l.offer_code) {
      angle = "offer";
      subject = "Making it right";
      goal = "Acknowledge their earlier experience, kindly and briefly. Say you would like to make it easier for them to give the product another try. Ask whether that would be helpful.";
      fixed_line = "If it helps, I can arrange " + l.offer_desc + ".";
    } else {
      angle = "checkin";
      subject = "Checking in";
      goal = "A soft check-in. Ask whether anything has changed on their side since they left. No pitch and no offer.";
    }
  } else {
    angle = "final";
    subject = "A final note from me";
    goal = "A polite final note. Say this is the last time you will reach out and that the door is always open. Ask whether they would like you to keep in touch or close their file.";
  }

  return { json: {
    ...l,
    angle,
    subject,
    goal,
    reason_phrase: (t === 2 || angle === "updates") ? "" : (reasonPhrase[l.cancel_reason] || ""),
    fixed_line,
    days_since_cancel: Math.floor((Date.now() - new Date(l.cancelled_at)) / 86400000)
  }};
});

