parameters.jsCode:
const src = $('Loop Winbacks').item.json;
const raw = $json.output?.[0]?.content?.[0]?.text ?? "";

const fallbackQuestion = {
  thanks:  "What is the one thing that would have made you stay?",
  updates: "Would you like to take a look?",
  offer:   "Would you like to take a second look?",
  checkin: "Has anything changed on your side since you left?",
  final:   "Would you like me to keep in touch, or close your file?"
};
// safe, code-written openers used only when the AI's own text is unusable
const fallbackOpener = {
  thanks:  "Thank you for having been a customer of ours, and I would genuinely value your honest feedback.",
  updates: "I wanted to reach out with a quick note now that some time has passed.",
  offer:   "I would like to make it easier for you to consider coming back.",
  checkin: "I wanted to reach out and see how things are on your side.",
  final:   "This will be my last note, and the door is always open if things change on your side."
};

// whole-word matches only
const survRe = /\b(notice[ds]?|noticing|saw|seems?|appears?|looks like|logged|logging in|log in|logins?|usage|activity|inactive|analytics|tracking|our data|monitor\w*)\b/i;
const pressureRe = /\b(miss(?:ed)? you|expires?|last chance|limited time|hurry|deadline|act now|only \d+ (?:days|hours))\b/i;
const productRe = /\b(features?|functionality|evolv\w*|building|built|adding|added|enhanc\w*|upgrad\w*|updates?|improvements?|new|shipped|launched|released)\b/i;
const moneyRe = /discount|coupon|free (?:month|trial)|\d+\s?%|\bprice\b|\bpricing\b|\boffer(?:s|ed|ing)?\b/i;
// reason words are only allowed when they match the customer's real reason
const costRe = /\b(cost|costs|costly|expensive|afford\w*|budget\w*|cheap\w*)\b/i;
const supportRe = /\b(support|service team|help desk)\b/i;

// the model should return plain text; if it returns JSON anyway, pull the body out
let core = raw.replace(/`/g, "").trim();
if (core.startsWith("{")) {
  try {
    core = String(JSON.parse(core).body || "").trim();
  } catch (e) {
    const m = core.match(/"body"\s*:\s*"([\s\S]*?)"\s*[,}]/);
    core = m ? m[1].replace(/\\n/g, " ").trim() : "";
  }
}
core = core.replace(/^["']+|["']+$/g, "").trim();
core = core.replace(/^(hi|hello|hey|dear)\b[^\n]*?,\s*/i, "");
core = core.replace(/[\s,]*(best regards|kind regards|warm regards|regards|best|thanks|cheers|sincerely)?[,\s]*CJ\s*$/i, "").trim();
core = core.replace(/\s*\n+\s*/g, " ");

// which reason words this customer's email may legitimately use
const costOk = src.cancel_reason === "PRICE";
const supportOk = src.cancel_reason === "SUPPORT_BAD";

// REPAIR: drop risky sentences, keep only the last question
const sentences = (core.match(/[^.?!]+[.?!]+(?:\s|$)|[^.?!]+$/g) || [core]).map(s => s.trim()).filter(Boolean);
const dropped = [];
const kept = sentences.filter(s => {
  if (survRe.test(s) || pressureRe.test(s) || productRe.test(s) || moneyRe.test(s)) { dropped.push(s); return false; }
  if ((!costOk && costRe.test(s)) || (!supportOk && supportRe.test(s))) { dropped.push(s); return false; }
  return true;
});
const questions = kept.filter(s => s.endsWith("?"));
let statements = kept.filter(s => !s.endsWith("?"));
questions.slice(0, -1).forEach(q => dropped.push(q));
const finalQuestion = questions.length ? questions[questions.length - 1] : fallbackQuestion[src.angle];

// if almost nothing usable is left, use the safe code-written opener
const statementWords = statements.join(" ").split(/\s+/).filter(Boolean).length;
let usedFallback = false;
if (statementWords < 8) {
  statements = [fallbackOpener[src.angle]];
  usedFallback = true;
}

const modelText = [...statements, finalQuestion].join(" ");
const middle = [...statements, src.fixed_line, finalQuestion].filter(Boolean).join(" ");
const body = `Hi ${src.first_name},\n\n${middle}\n\nCJ`;

const words = modelText.split(/\s+/).filter(Boolean).length;
const qCount = (middle.match(/\?/g) || []).length;
const pcts = [...body.matchAll(/(\d+)\s?%/g)].map(m => Number(m[1]));
const surv = modelText.match(survRe);

const checks = {
  hasBody:         modelText.length > 30,
  lengthOk:        words >= 12 && words <= 90,
  noPlaceholders:  !/\[.*?\]|\{\{.*?\}\}|XYZ|Lorem/i.test(modelText),
  noMoneyTalk:     !moneyRe.test(modelText),
  noProductClaims: !productRe.test(modelText),
  noWrongReason:   (costOk || !costRe.test(modelText)) && (supportOk || !supportRe.test(modelText)),
  offerGrounded:   pcts.every(n => n === Number(src.discount_pct)) && (pcts.length === 0 || src.angle === "offer"),
  noSurveillance:  !surv,
  noPressure:      !pressureRe.test(modelText),
  noEmDash:        !/[—–]/.test(modelText),
  noExclaim:       !/!/.test(modelText),
  noStrayNames:    !/\bCJ\b/.test(modelText) && !modelText.includes(src.first_name) && !modelText.includes(src.company),
  noPlanMention:   !new RegExp("\\b" + src.plan + "\\s+(plan|tier|subscription)\\b", "i").test(modelText),
  oneQuestion:     qCount === 1
};

// plain-English reasons, so the alert makes sense to a human
const reasons = {
  hasBody:         "The email text was too short to send.",
  lengthOk:        `The email text was ${words} words after cleanup (it needs 12 to 90).`,
  noPlaceholders:  "The AI left a placeholder like [name] in the text.",
  noMoneyTalk:     "The AI brought up prices or discounts on its own.",
  noProductClaims: "The AI made claims about the product on its own.",
  noWrongReason:   "The AI stated a reason for leaving that does not match why this customer cancelled.",
  offerGrounded:   "A percentage in the email did not match the real offer.",
  noSurveillance:  `The AI implied we were watching their activity${surv ? ` (it used "${surv[0]}")` : ""}.`,
  noPressure:      "The AI used pressure or guilt wording.",
  noEmDash:        "The AI used a dash character we do not allow.",
  noExclaim:       "The AI used an exclamation mark.",
  noStrayNames:    "The AI wrote a name (CJ, the customer, or the company) inside the body.",
  noPlanMention:   "The AI mentioned the customer's plan name.",
  oneQuestion:     `The email had ${qCount} questions instead of exactly 1.`
};

const failed = Object.entries(checks).filter(([, v]) => !v).map(([k]) => reasons[k]);

return { json: {
  ...src,
  body,
  word_count: words,
  used_fallback: usedFallback,
  repaired: dropped,
  valid: failed.length === 0,
  fail: failed.join(" "),
  raw_output: raw.slice(0, 400)
}};

