parameters.jsCode:
const body = String($json.textPlain || "").replace(/\r/g, "");

// keep only what the person actually wrote, drop the quoted history
const cutAt = body.search(/\n\s*On [\s\S]{0,200}?wrote:|\n-{3,}\s*Original Message|\n>/i);
const reply = (cutAt === -1 ? body : body.slice(0, cutAt)).trim().slice(0, 1500);

// every email address in From and To, so the database can decide which is a customer
const found = (String($json.from || "") + " " + String($json.to || ""))
  .match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [];
const candidates = [...new Set(found.map(e => e.toLowerCase()))];

return { json: {
  subject: $json.subject || "",
  reply,
  candidates,
  message_id: $json.metadata?.["message-id"] || ""
}};

const allowed = ["WANTS_TO_RETURN", "QUESTION", "PRICE_OBJECTION", "NOT_INTERESTED", "UNSUBSCRIBE", "AUTO_REPLY"];
const raw = String($json.output?.[0]?.content?.[0]?.text ?? "").toUpperCase();
const modelCategory = allowed.find(c => new RegExp("\\b" + c + "\\b").test(raw));

const clean = $('Clean Reply').first().json;
const customer = $('Find Customer').first().json || {};
const reply = clean.reply || "";
const subject = clean.subject || "";

const autoReplyRe = /automatic reply|auto-?reply|out of office|undeliverable|delivery status notification|mail delivery/i;
const unsubscribeRe = /\bunsubscribe\b|^\s*stop\b|\bstop (?:emailing|sending|contacting|messaging)\b|\bremove me\b|\btake me off\b|\bdo not (?:contact|email)\b|\bdon'?t (?:contact|email)\b|\bopt[ -]?out\b|\bleave me alone\b|\bspam\b/i;

let category, source;
if (autoReplyRe.test(subject)) {
  category = "AUTO_REPLY"; source = "code: auto-reply or bounce subject";
} else if (unsubscribeRe.test(reply)) {
  category = "UNSUBSCRIBE"; source = "code: unsubscribe wording";
} else if (modelCategory) {
  category = modelCategory; source = "model";
} else {
  category = "QUESTION"; source = "fallback: model answer not recognised";
}

return { json: {
  customer_found: Boolean(customer.id),
  id: customer.id || null,
  first_name: customer.first_name || null,
  company: customer.company || null,
  email: customer.email || null,
  mrr: customer.mrr || null,
  status: customer.status || null,
  cancel_reason: customer.cancel_reason || null,
  subject,
  reply,
  category,
  category_source: source,
  model_output: raw.slice(0, 60)
}};

